    descriptionAdvanced: {
      de: "Bandar Seri Begawan, die Hauptstadt des Sultanats Brunei Darussalam, ist eine Stadt von außergewöhnlicher Eleganz und religiöser Bedeutung auf der Insel Borneo. Sie liegt am Nordufer des Brunei-Flusses und ist bekannt für ihren Reichtum, der primär auf den riesigen Erdöl- und Erdgasvorkommen des Landes basiert. Das Stadtbild wird von prachtvollen goldgekrönten Moscheen dominiert, allen voran die Sultan-Omar-Ali-Saifuddin-Moschee, die als eine der schönsten im asiatisch-pazifischen Raum gilt. Ihr künstlicher See und die Marmorfassade symbolisieren den spirituellen Reichtum des Sultanats. Ein einzigartiger Kontrast dazu ist Kampong Ayer, das größte Wasserdorf der Welt, in dem Zehntausende Menschen in auf Stelzen gebauten Häusern über dem Fluss leben. Dieses 'Venedig des Ostens' verfügt über eigene Schulen, Krankenhäuser und Feuerwehren, allesamt auf dem Wasser. Bandar Seri Begawan ist auch der Sitz des Sultans von Brunei; der Istana Nurul Iman ist der größte bewohnte Palast der Welt und ein Monument absoluter Monarchie und Opulenz. Die Stadt ist sauber, geordnet und verfügt über eine hochmoderne Infrastruktur, die den hohen Lebensstandard der Bürger widerspiegelt. Wirtschaftlich ist sie das Finanzzentrum Bruneis, wobei der staatliche Sektor und die Energiewirtschaft die Hauptarbeitgeber sind. Trotz der Modernisierung ist die Stadt von dichtem tropischem Regenwald umgeben, der oft bis an die Stadtgrenzen reicht und eine grüne Lunge bildet. Das Royal Regalia Museum bietet Besuchern Einblicke in die zeremoniellen Traditionen und den Lebensweg des Sultans. Bandar Seri Begawan ist weniger eine hektische Metropole als vielmehr ein ruhiges, würdevolles Zentrum islamischer Kultur und malaiischer Tradition, das Tradition und Moderne harmonisch vereint. Die Stadtplanung legt großen Wert auf den Erhalt der Umwelt und die Förderung der sozialen Wohlfahrt, was sie zu einer der lebenswertesten Städte in Südostasien macht.",
      hu: "Bandar Seri Begawan Brunei Szultanátus fővárosa és egyben legnagyobb városa, amely Borneo szigetének északi részén, a Brunei-folyó partján fekszik. A város neve tükrözi jelentőségét: a 'Bandar' kikötőt, a név többi része pedig a szultáni méltóságra utal. A városkép meghatározó elemei a csillogó aranykupolás mecsetek, amelyek közül kiemelkedik az Omar Ali Saifuddien mecset, Brunei egyik legfontosabb jelképe. A szultánság hatalmas kőolaj- és földgázkészleteinek köszönhetően a város a modern jólét szigete, ahol a luxus és a vallási hagyományok kéz a kézben járnak. Különleges látványosság a Kampong Ayer, a világ legnagyobb cölöpökre épült vízi faluja, amely évszázadok óta a helyi életmód alapköve, és modern kényelmi szolgáltatásokkal felszerelve dacol az idővel. Bandar Seri Begawan ad otthont az Istana Nurul Iman palotának, amely a világ legnagyobb lakott uralkodói rezidenciája, több mint 1700 szobával. A város gazdasági élete a szénhidrogén-exportra és az állami adminisztrációra épül, miközben a turizmus is egyre nagyobb szerephez jut. A környező trópusi esőerdők közelsége és a gondosan ápolt parkok miatt a település rendkívül zöld és levegős. A Királyi Jelvények Múzeuma (Royal Regalia Museum) bemutatja az uralkodó család pompáját és Brunei történelmét. A város lakói élvezik az ingyenes egészségügyet és oktatást, ami hozzájárul a stabil és békés társadalmi környezethez. Bandar Seri Begawan nem csupán politikai központ, hanem a maláj kultúra és az iszlám vallás délkelet-ázsiai fellegvára, ahol a mindennapokat a vallási előírások és a tradicionális értékrend határozza meg. A modern infrastruktúra, az alacsony bűnözési ráta és a tisztaság miatt a város az egyik legvonzóbb célpont a régióban a minőségi életet keresők számára.",
      ro: "Bandar Seri Begawan, capitala strălucitoare a Sultanatului Brunei, este o metropolă unde opulența modernă se întâlnește cu tradiția islamică profundă pe insula Borneo. Situat pe malurile fluviului Brunei, orașul a fost redenumit în 1970 în onoarea tatălui actualului sultan, marcând o eră de modernizare accelerată finanțată de bogatele resurse de petrol și gaze. Reperele sale arhitecturale sunt dominate de Moscheea Sultan Omar Ali Saifuddien, cu domurile sale placate cu aur pur, care reflectă în lacul artificial din jur o imagine de o frumusețe rară. Istana Nurul Iman, palatul oficial al sultanului, deține recordul mondial pentru cea mai mare rezidență regală locuită, fiind un simbol al puterii și stabilității monarhiei bruneiene. O caracteristică unică a orașului este Kampong Ayer, 'Veneția Estului', un complex vast de sate pe piloni care găzduiește o parte semnificativă a populației capitalei, oferind o perspectivă autentică asupra modului de viață tradițional malaezian. Economia orașului este centrată pe sectorul energetic și pe cel financiar, Bandar Seri Begawan fiind sediul celor mai importante instituții de stat și bănci internaționale. Curățenia exemplară, siguranța publică ridicată și absența aglomerației urbane tipice altor capitale asiatice fac din Bandar Seri Begawan un loc de o demnitate aparte. Orașul este înconjurat de o vegetație luxuriantă, autoritățile investind masiv în conservarea naturii și în parcuri urbane precum Tasek Lama. Muzeul Regaliilor Regale oferă o incursiune în ceremoniile de încoronare și în cadourile diplomatice primite de suveran, subliniind legăturile internaționale ale țării. Bandar Seri Begawan nu este doar un centru administrativ, ci și inima culturală a Bruneiului, unde festivalurile religioase și evenimentele regale definesc ritmul vieții publice. Această capitală reprezintă un model de echilibru între conservarea valorilor religioase și adoptarea tehnologiilor de ultimă oră pentru bunăstarea cetățenilor săi.",
      en: "Bandar Seri Begawan, the serene capital of Brunei Darussalam, is a city defined by its immense oil wealth, Islamic devotion, and unique water-based heritage. Located on the northern banks of the Brunei River on the island of Borneo, the city serves as the undisputed center of political and financial power in the Sultanate. The skyline is characterized by magnificent religious structures, most notably the Sultan Omar Ali Saifuddien Mosque, often described as one of the most beautiful mosques in the world, featuring a golden dome that sparkles under the tropical sun. Directly across the modern city center lies Kampong Ayer, the world's largest water village, where a vibrant community lives in houses perched on stilts over the river. This historic settlement, equipped with its own schools and fire stations, represents the traditional roots of the Bruneian people amidst a rapidly modernizing nation. Bandar Seri Begawan is also home to the Istana Nurul Iman, the official residence of the Sultan of Brunei and the largest residential palace in the world, symbolizing the absolute monarchy's stability and grandeur. The city's economy is heavily reliant on the hydrocarbon industry, which provides for one of the highest standards of living in Asia, including free healthcare and education for its citizens. Despite its wealth, the capital retains a quiet and orderly atmosphere, far removed from the chaotic urban sprawl of neighboring Southeast Asian capitals. Lush rainforests border the city, and conservation efforts ensure that greenery remains an integral part of the urban experience. Visitors can explore the Royal Regalia Museum, which houses a vast collection of ceremonial items belonging to the Sultan, and the Brunei Museum, which offers insights into the region's Islamic art and natural history. Bandar Seri Begawan is a place where traditional Malay values and modern prosperity coexist harmoniously, guided by the national philosophy of Melayu Islam Beraja (Malay Islamic Monarchy).",
    },
