      de: ["Bandar Seri Begawan wurde 1970 nach dem 28. Sultan von Brunei umbenannt.", "Die Sultan-Omar-Ali-Saifuddin-Moschee verfügt über eine Kuppel aus reinem Gold.", "Der Palast Istana Nurul Iman hat 1.788 Zimmer und 257 Badezimmer.", "Kampong Ayer beherbergt etwa 30.000 Menschen auf dem Wasser des Brunei-Flusses.", "Die Stadt hat ein tropisches Regenwaldklima mit hoher Luftfeuchtigkeit das ganze Jahr.", "Brunei erhebt keine Einkommensteuer für die Einwohner von Bandar Seri Begawan.", "Das Royal Regalia Museum beherbergt den goldenen Prunkwagen für Krönungszeremonien.", "Die Brücke Jame' 'Asr Hassanil Bolkiah ist ein weiteres architektonisches Highlight."],
      hu: ["A várost 1970 előtt egyszerűen Brunei Townnak hívták.", "Az Istana Nurul Iman palota alapterülete több mint 200 000 négyzetméter.", "Kampong Ayer vízi faluja már több mint 1300 éve lakott terület.", "Az Omar Ali Saifuddien mecset márványát Olaszországból, szőnyegeit Belgiumból hozták.", "A város Brunei egyetlen nemzetközi repülőterének, a Brunei Internationalnak a bázisa.", "A benzin ára a szubvencióknak köszönhetően a világon itt az egyik legalacsonyabb.", "A Royal Regalia Museum belépése ingyenes, és bemutatja a szultáni koronázási ékszereket.", "A várost sűrű mangroveerdők veszik körül, amelyek gazdag élővilágnak adnak otthont."],
