      hu: ["A Tutong folyó mentén fekszik.", "Híres a Pantai Seri Kenangan strandról."],
      ro: ["Situat de-a lungul râului Tutong.", "Renumit pentru Pantai Seri Kenangan."],
      en: ["Located along the Tutong River.", "Famous for Pantai Seri Kenangan."],
