      en: ["Jerudong Park Playground officially opened to the public in 1994.", "Michael Jackson performed a free concert here in 1996 for the Sultan's birthday.", "The area hosts The Empire Brunei, one of the world's most luxurious resorts.", "Jerudong is the site of the specialized Jerudong Park Medical Centre.", "The Royal Brunei Polo Club frequently hosts international tournaments.", "The local fish market is a major attraction for residents seeking fresh seafood."],
      es: ["Jerudong Park fue inaugurado oficialmente en 1994.", "Michael Jackson dio un concierto gratuito aquí en 1996 por el cumpleaños del Sultán.", "El lugar alberga el lujoso hotel Empire Brunei junto al mar.", "En Jerudong se encuentra el especializado Jerudong Park Medical Centre.", "El club de polo es utilizado frecuentemente por miembros de la familia real.", "El mercado local de pescado (Pasar Ikan) es conocido por sus mariscos frescos."],
