      fr: ["Le Jerudong Park a été officiellement inauguré en 1994.", "Michael Jackson y a donné un concert gratuit en 1996 pour l'anniversaire du Sultan.", "Le lieu abrite le luxueux hôtel Empire Brunei au bord de la mer.", "Jerudong accueille le centre médical spécialisé Jerudong Park Medical Centre.", "Le club de polo est souvent utilisé par des membres de la famille royale.", "Le marché aux poissons local (Pasar Ikan) est réputé pour ses produits frais."],
