      pt: ["Mentiri abriga um dos maiores projetos estatais de habitação (RPN).", "O Pantai Mentiri Golf Club foi inaugurado oficialmente em 1983.", "A localidade situa-se na estrada de ligação para Muara e Temburong.", "A área é caracterizada por colinas suaves e floresta tropical secundária.", "Mentiri tem a sua própria grande escola primária estatal e escolas secundárias.", "Perto encontra-se a pitoresca zona húmida de Sungai Buloh."],
      fr: ["Mentiri abrite l'un des plus grands projets de logements sociaux (RPN).", "Le Pantai Mentiri Golf Club a été officiellement inauguré en 1983.", "La localité se trouve sur la route reliant Muara et Temburong.", "La région est marquée par des collines douces et une forêt tropicale secondaire.", "Mentiri possède ses propres grandes écoles primaires et secondaires publiques.", "La zone humide pittoresque de Sungai Buloh se trouve à proximité."],
