      hu: ["Lumapas közigazgatásilag a Mukim Lumapas egységhez tartozik.", "A Bukit Lumapas domb népszerű túraútvonalakat kínál.", "A terület Brunei egyik fontos zöldség- és gyümölcstermesztő vidéke.", "A RIPAS-híd megnyitása előtt csak hosszú kerülővel volt elérhető a főváros.", "Lumapas déli határa mentén Malajzia (Sarawak állam) fekszik.", "A környék megőrizte hagyományos falusi (kampong) jellegét."],
      ro: ["Lumapas este administrat ca un mukim (subdistrict) în Brunei-Muara.", "Dealul Bukit Lumapas atrage numeroși pasionați de trekking în weekend.", "Zona contribuie semnificativ la producția locală de fructe și legume.", "Podul RIPAS a eliminat izolarea geografică a localității față de capitală.", "Lumapas are o graniță terestră directă cu statul malaezian Sarawak.", "Peisajul este dominat de ferme de familie și păduri secundare."],
      en: ["Lumapas is administratively organized as Mukim Lumapas.", "Bukit Lumapas is a well-known hill frequented by local hikers.", "The area is a significant contributor to Brunei's local produce market.", "The RIPAS Bridge provides a high-speed link to Bandar Seri Begawan.", "Lumapas shares a land border with the Malaysian state of Sarawak.", "The community maintains a strong traditional 'kampong' (village) identity."],
      es: ["Lumapas es administrativamente conocido como Mukim Lumapas.", "La colina Bukit Lumapas es un destino popular para excursionistas locales.", "La zona es uno de los principales proveedores de frutas y verduras locales.", "El puente Ripas acorta el viaje a la capital a pocos minutos.", "Lumapas limita al sur directamente con la frontera de Malasia (Sarawak).", "En la región hay varios manantiales naturales y arroyos."],
      pt: ["Lumapas é administrativamente conhecido como Mukim Lumapas.", "A colina Bukit Lumapas é um destino popular para caminhantes locais.", "A zona é um dos principais fornecedores de frutas e vegetais locais.", "A ponte Ripas encurta a viagem até à capital para poucos minutos.", "Lumapas faz fronteira a sul diretamente com a fronteira da Malásia (Sarawak).", "Existem várias nascentes naturais e ribeiros na região."],
