      pt: ["Pertence ao distrito de Brunei-Muara.", "Localizado perto da capital Bandar Seri Begawan.", "Abrange várias aldeias (Kampongs).", "Primordialmente uma área residencial e agrícola.", "Abriga a Escola Primária Kilanas.", "Parte importante da área metropolitana."],
