      ro: ["Sungai Akar se află în districtul Brunei-Muara, cea mai populată regiune.", "Sediul Radio Television Brunei (RTB) este situat în această zonă.", "Regiunea este renumită pentru relieful său deluros și peisajul verde.", "Multe ambasade și misiuni diplomatice își au sediul în acest cartier.", "Zona este situată la circa 10 minute de mers cu mașina de aeroport.", "Din punct de vedere administrativ, face parte din Mukim Berakas 'B'."],
      en: ["Sungai Akar is located in the Brunei-Muara District, the most populous region.", "The Radio Television Brunei (RTB) broadcasting center is located here.", "The area is known for its hilly terrain and lush greenery.", "Several important diplomatic missions are based in this neighborhood.", "The district is roughly 10 minutes by car from the international airport.", "It is part of the administrative division known as Mukim Berakas 'B'."],
