      hu: ["A Brunei-Muara körzetben található.", "Berakas \"A\" és Berakas \"B\" körzetek része.", "Lambak Kanan lakásprojektként indult az 1980-as években.", "Brunei Nemzetközi Repülőtere közelében fekszik.", "Itt található a Lambak Kanan mecset.", "A Nemzeti Lakásépítési Program (RPN) központi eleme."],
